1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! The per-process file-descriptor table (slice 5.4, mutable since 5.8).
4	//!
5	//! VFS's whole job is turning a small integer into a thing that can be read from
6	//! or written to. This module is that mapping and nothing else: pure, total, and
7	//! host-tested, with the IPC glue in `main.rs` — the `servers/ds` `registry.rs` /
8	//! `main.rs` split.
9	//!
10	//! ## Every process starts with the same three descriptors
11	//!
12	//! fds 0, 1, and 2 name the console character device in every row. That is the
13	//! POSIX convention — a process inherits stdin/stdout/stderr rather than opening
14	//! them — and it is what lets init write a banner before a filesystem exists.
15	//! Everything above them starts closed and is handed out by [`alloc_in`].
16	//!
17	//! ## The storage became interior-mutable, and that is the hazard
18	//!
19	//! Until slice 5.8 nothing mutated, so the table was an ordinary immutable
20	//! `static` and this crate carried no `unsafe` at all. `open`/`close` changed
21	//! that: it is now an `UnsafeCell<[FdRow; N]>` + `unsafe impl Sync` newtype, the
22	//! shape `servers/vm/src/region.rs` and `servers/ds/src/registry.rs` already use,
23	//! under the same single-mutator invariant (VFS is one EL0 thread running a
24	//! straight-line receive loop, with no interrupt handlers of its own).
25	//!
26	//! **The rule that comes with it: never hold a borrow of the table across a
27	//! SENDREC.** A handler resolves a descriptor, sends a request to MFS or TTY —
28	//! which blocks, and during which nothing else touches the table, but the borrow
29	//! would still be live across a call that can reach `alloc_in`/`close_in` in a
30	//! later refactor — and then updates the position. [`Fd`] is `Copy` precisely so
31	//! that is easy to obey: the borrow dies at the destructuring `let`, and the
32	//! handler carries values.
33	//!
34	//! This is not a theoretical concern. CLAUDE.md records aliasing-through-an
35	//! -`UnsafeCell`-newtype as a class of bug this repo has *shipped* (slice 5.3's
36	//! `free_frame` / `is_usable_pa`), caught in review rather than by a test. The
37	//! pure `*_in` helpers below all take the rows as a borrowed slice, which is what
38	//! keeps every decision testable without touching the static at all.
39	
40	use minixrs_kernel_shared::callnr::CDEV_MINOR_CONSOLE;
41	use minixrs_kernel_shared::com::NR_SERVED_PROCS;
42	use minixrs_kernel_shared::error::{EBADF, EMFILE};
43	
44	use core::cell::UnsafeCell;
45	
46	/// Descriptors per process.
47	///
48	/// Three are pre-opened (stdin/stdout/stderr), which leaves five for `open` to
49	/// hand out. Five rather than one is what makes "the lowest free descriptor" and
50	/// "the row is full" *separate* things a test can tell apart: with `NR_FDS = 4`
51	/// the first `open` would also be the last, and an allocator that scanned from
52	/// the wrong end would be indistinguishable from one that scanned correctly.
53	///
54	/// VFS-local, deliberately **not** part of the ABI: a client learns a descriptor
55	/// is bad from `EBADF` and that the table is full from `EMFILE`, never from
56	/// arithmetic on a published constant.
57	pub const NR_FDS: usize = 8;
58	
59	/// What a descriptor refers to.
60	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
61	pub enum Fd {
62	    /// Not open. Every operation on it is `EBADF`.
63	    Unused,
64	    /// A character device — today only the console, via `CDEV_WRITE` to TTY.
65	    CharDev {
66	        /// Device minor, e.g. [`CDEV_MINOR_CONSOLE`]. Passed through to the
67	        /// driver, which is the one that decides whether it exists (`ENXIO`).
68	        minor: i32,
69	    },
70	    /// A regular file on the mounted filesystem.
71	    File {
72	        /// The inode, as MFS handed it out from an `FS_LOOKUP`.
73	        ino: u32,
74	        /// The seek position. Advanced by [`advance_in`] after each read.
75	        pos: u64,
76	    },
77	}
78	
79	/// One process's descriptors, indexed by descriptor number.
80	pub type FdRow = [Fd; NR_FDS];
81	
82	/// The descriptors every process is born with: 0, 1, and 2 on the console.
83	const DEFAULT_ROW: FdRow = {
84	    let mut row = [Fd::Unused; NR_FDS];
85	    row[0] = Fd::CharDev {
86	        minor: CDEV_MINOR_CONSOLE,
87	    };
88	    row[1] = Fd::CharDev {
89	        minor: CDEV_MINOR_CONSOLE,
90	    };
91	    row[2] = Fd::CharDev {
92	        minor: CDEV_MINOR_CONSOLE,
93	    };
94	    row
95	};
96	
97	/// The first descriptor `open` may hand out. Everything below is pre-opened.
98	pub const FIRST_FREE_FD: usize = 3;
99	
100	/// Rows in the table — one per process, indexed by **kernel proc number**.
101	///
102	/// Sized from [`NR_SERVED_PROCS`], the single shared ceiling PM's `mproc`, VM's
103	/// `ClientRegions`, and SCHED's policy table all derive from, so a process that
104	/// exists to one server is addressable in all of them. Never reintroduce an
105	/// independent capacity literal here: the guard below is what makes an
106	/// under-sized edit a compile error rather than a runtime `EBADF` that only the
107	/// highest-numbered processes ever see. Same shape as VM's `MAX_CLIENTS`.
108	const NR_FD_ROWS: usize = NR_SERVED_PROCS;
109	
110	const _: () = assert!(NR_FD_ROWS >= NR_SERVED_PROCS);
111	const _: () = assert!(NR_FDS > FIRST_FREE_FD);
112	
113	/// `UnsafeCell`-wrapped static table. See the module note for the single-mutator
114	/// invariant and the borrow rule that comes with it.
115	#[repr(transparent)]
116	struct Table(UnsafeCell<[FdRow; NR_FD_ROWS]>);
117	
118	// SAFETY: VFS is a single EL0 thread running a straight-line receive loop with no
119	// interrupt handlers of its own, so there is never a second accessor. Every path
120	// to the table goes through the four wrappers below, each of which takes its
121	// borrow and releases it within one call.
122	unsafe impl Sync for Table {}
123	
124	static ROWS: Table = Table(UnsafeCell::new([DEFAULT_ROW; NR_FD_ROWS]));
125	
126	/// Resolve `(proc_nr, fd)` against a borrowed table.
127	///
128	/// The pure half — `rows` is passed in so this is testable without touching the
129	/// static, which is what let it survive slice 5.8's switch to interior-mutable
130	/// storage completely unchanged.
131	///
132	/// `EBADF` for every way of naming nothing: a negative descriptor, one past the
133	/// end of the row, a descriptor that is not open, and a proc number outside the
134	/// table. The last of those is the interesting one — it is how a message from a
135	/// process VFS has no row for (a proc number beyond `NR_SERVED_PROCS`, or the
136	/// negative number of a kernel task) fails closed rather than indexing wild.
137	pub fn resolve_in(rows: &[FdRow], proc_nr: i32, fd: i32) -> Result<Fd, i32> {
138	    let Ok(slot) = usize::try_from(proc_nr) else {
139	        return Err(EBADF);
140	    };
141	    let Ok(idx) = usize::try_from(fd) else {
142	        return Err(EBADF);
143	    };
144	    match rows.get(slot).and_then(|row| row.get(idx)) {
145	        Some(Fd::Unused) | None => Err(EBADF),
146	        Some(open) => Ok(*open),
147	    }
148	}
149	
150	/// Install `entry` at the **lowest free descriptor** of `proc_nr`'s row and
151	/// return its number.
152	///
153	/// Lowest-free is POSIX's rule, and it is the one thing about `open` a client can
154	/// observe without reading the file: close a descriptor and the next `open`
155	/// reuses that number. It is also why the search must run *upwards* — a
156	/// `.rposition()` would hand out `NR_FDS - 1` first, pass every "did I get a
157	/// descriptor" check, and silently break the contract.
158	///
159	/// `EMFILE` when the row is full, `EBADF` for a proc number outside the table.
160	/// The scan starts at [`FIRST_FREE_FD`] rather than 0: 0/1/2 are pre-opened and
161	/// nothing ever closes them, so starting lower would only waste three
162	/// comparisons — but stating it means a future `close(1)` cannot silently make
163	/// `open` hand out a standard descriptor.
164	pub fn alloc_in(rows: &mut [FdRow], proc_nr: i32, entry: Fd) -> Result<i32, i32> {
165	    let Ok(slot) = usize::try_from(proc_nr) else {
166	        return Err(EBADF);
167	    };
168	    let row = rows.get_mut(slot).ok_or(EBADF)?;
169	    for (fd, cell) in row.iter_mut().enumerate().skip(FIRST_FREE_FD) {
170	        if *cell == Fd::Unused {
171	            *cell = entry;
172	            // `NR_FDS` is 8, so this cannot exceed `i32::MAX`; the guard below is
173	            // for the day it is raised from a shared constant.
174	            return i32::try_from(fd).map_err(|_| EMFILE);
175	        }
176	    }
177	    Err(EMFILE)
178	}
179	
180	/// Close `fd` in `proc_nr`'s row.
181	///
182	/// `EBADF` for a descriptor that was not open — closing twice is an error, not a
183	/// no-op, which is what makes the `fs.fd` boot probe's re-open meaningful.
184	pub fn close_in(rows: &mut [FdRow], proc_nr: i32, fd: i32) -> Result<(), i32> {
185	    let (Ok(slot), Ok(idx)) = (usize::try_from(proc_nr), usize::try_from(fd)) else {
186	        return Err(EBADF);
187	    };
188	    let cell = rows
189	        .get_mut(slot)
190	        .and_then(|row| row.get_mut(idx))
191	        .ok_or(EBADF)?;
192	    if *cell == Fd::Unused {
193	        return Err(EBADF);
194	    }
195	    *cell = Fd::Unused;
196	    Ok(())
197	}
198	
199	/// Advance a file descriptor's position by `n` bytes.
200	///
201	/// A no-op for anything that is not a [`Fd::File`] — a character device has no
202	/// position — and `saturating_add`, because a position that wrapped would send
203	/// the next read back to the start of the file rather than reporting EOF.
204	///
205	/// Silently ignoring a bad descriptor is right here and only here: this is called
206	/// *after* a successful transfer, so the descriptor was resolved a moment ago and
207	/// there is nothing left to tell the caller. Every path that can refuse has
208	/// already refused.
209	pub fn advance_in(rows: &mut [FdRow], proc_nr: i32, fd: i32, n: u64) {
210	    let (Ok(slot), Ok(idx)) = (usize::try_from(proc_nr), usize::try_from(fd)) else {
211	        return;
212	    };
213	    if let Some(Fd::File { pos, .. }) = rows.get_mut(slot).and_then(|row| row.get_mut(idx)) {
214	        *pos = pos.saturating_add(n);
215	    }
216	}
217	
218	/// Resolve `(proc_nr, fd)` against the live table.
219	pub fn resolve(proc_nr: i32, fd: i32) -> Result<Fd, i32> {
220	    // SAFETY: single-mutator invariant (see the module note). The borrow is taken
221	    // and released entirely within this call, so it cannot be held across a
222	    // SENDREC — `Fd` is `Copy`, so the value the caller keeps borrows nothing.
223	    resolve_in(unsafe { &*ROWS.0.get() }, proc_nr, fd)
224	}
225	
226	/// Install `entry` at the lowest free descriptor of the live table.
227	pub fn alloc(proc_nr: i32, entry: Fd) -> Result<i32, i32> {
228	    // SAFETY: as `resolve` — one mutator, and the borrow does not escape.
229	    alloc_in(unsafe { &mut *ROWS.0.get() }, proc_nr, entry)
230	}
231	
232	/// Close `fd` in the live table.
233	pub fn close(proc_nr: i32, fd: i32) -> Result<(), i32> {
234	    // SAFETY: as `resolve` — one mutator, and the borrow does not escape.
235	    close_in(unsafe { &mut *ROWS.0.get() }, proc_nr, fd)
236	}
237	
238	/// Advance a descriptor's position in the live table.
239	pub fn advance(proc_nr: i32, fd: i32, n: u64) {
240	    // SAFETY: as `resolve` — one mutator, and the borrow does not escape.
241	    advance_in(unsafe { &mut *ROWS.0.get() }, proc_nr, fd, n)
242	}
243	
244	#[cfg(test)]
245	mod tests {
246	    use super::*;
247	
248	    const CONSOLE: Fd = Fd::CharDev {
249	        minor: CDEV_MINOR_CONSOLE,
250	    };
251	    const FILE: Fd = Fd::File { ino: 5, pos: 0 };
252	
253	    /// A private table to mutate, so no test can disturb the live one.
254	    fn rows() -> [FdRow; 2] {
255	        [DEFAULT_ROW; 2]
256	    }
257	
258	    #[test]
259	    fn stdin_stdout_and_stderr_are_the_console_for_every_process() {
260	        // The pre-open contract, checked across the whole proc-number range
261	        // rather than for one process: init, a boot server, and a forked child
262	        // must all find fd 1 without anything having opened it.
263	        for proc_nr in 0..NR_SERVED_PROCS as i32 {
264	            for fd in 0..3 {
265	                assert_eq!(resolve(proc_nr, fd), Ok(CONSOLE), "proc {proc_nr} fd {fd}");
266	            }
267	        }
268	    }
269	
270	    #[test]
271	    fn every_row_starts_identical_and_open_is_what_makes_them_diverge() {
272	        // Slice 5.4's `every_row_is_identical_today`, which slice 5.8 was always
273	        // going to break: the rows now *can* diverge. What is still true — and
274	        // what the loop above depends on — is that they start identical, so this
275	        // states the invariant that survived rather than deleting the test.
276	        let mut r = rows();
277	        assert_eq!(r[0], r[1]);
278	        assert_eq!(r[0], DEFAULT_ROW);
279	
280	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(3));
281	        assert_ne!(r[0], r[1], "open must affect only the caller's row");
282	        assert_eq!(r[1], DEFAULT_ROW);
283	    }
284	
285	    #[test]
286	    fn an_unopened_descriptor_is_ebadf() {
287	        // fd 3 exists in the row but holds `Unused` — the case that proves
288	        // "in range" and "open" are separate questions.
289	        assert_eq!(resolve_in(&rows(), 0, 3), Err(EBADF));
290	    }
291	
292	    #[test]
293	    fn a_descriptor_past_the_end_of_the_row_is_ebadf() {
294	        for fd in [NR_FDS as i32, NR_FDS as i32 + 1, 64, i32::MAX] {
295	            assert_eq!(resolve(0, fd), Err(EBADF), "fd {fd}");
296	        }
297	    }
298	
299	    #[test]
300	    fn a_negative_descriptor_is_ebadf() {
301	        // A client that passed through an errno by mistake, or a wrapped count.
302	        for fd in [-1i32, -3, i32::MIN] {
303	            assert_eq!(resolve(0, fd), Err(EBADF), "fd {fd}");
304	        }
305	    }
306	
307	    #[test]
308	    fn a_proc_number_outside_the_table_is_ebadf() {
309	        // Above the ceiling, and the negative numbers kernel tasks carry —
310	        // neither may index the table, and neither may panic. Every entry point,
311	        // not just `resolve`: a bad proc number reaching `alloc` or `close` would
312	        // otherwise index wild.
313	        for proc_nr in [
314	            NR_SERVED_PROCS as i32,
315	            NR_SERVED_PROCS as i32 + 1,
316	            -1,
317	            -2,
318	            i32::MIN,
319	            i32::MAX,
320	        ] {
321	            let mut r = rows();
322	            assert_eq!(resolve(proc_nr, 1), Err(EBADF), "proc {proc_nr}");
323	            assert_eq!(alloc_in(&mut r, proc_nr, FILE), Err(EBADF), "{proc_nr}");
324	            assert_eq!(close_in(&mut r, proc_nr, 1), Err(EBADF), "{proc_nr}");
325	            // `advance_in` has no way to report, so the assertion is that it
326	            // changes nothing rather than panicking.
327	            advance_in(&mut r, proc_nr, 1, 8);
328	            assert_eq!(r, rows());
329	        }
330	    }
331	
332	    #[test]
333	    fn resolve_in_reads_the_row_it_is_given() {
334	        // The pure helper must not reach the static: hand it a table whose fd 1
335	        // is closed and whose fd 3 is open, the opposite of the real one.
336	        let mut r = rows();
337	        r[1][1] = Fd::Unused;
338	        r[1][3] = Fd::CharDev { minor: 7 };
339	
340	        assert_eq!(resolve_in(&r, 0, 1), Ok(CONSOLE));
341	        assert_eq!(resolve_in(&r, 1, 1), Err(EBADF));
342	        assert_eq!(resolve_in(&r, 1, 3), Ok(Fd::CharDev { minor: 7 }));
343	        // ...and the static is unchanged, so the two really are independent.
344	        assert_eq!(resolve(1, 1), Ok(CONSOLE));
345	    }
346	
347	    #[test]
348	    fn an_empty_table_resolves_nothing() {
349	        // Degenerate borrow: no rows at all. `resolve_in` must answer `EBADF`
350	        // rather than index into a zero-length slice.
351	        assert_eq!(resolve_in(&[], 0, 1), Err(EBADF));
352	        assert_eq!(alloc_in(&mut [], 0, FILE), Err(EBADF));
353	        assert_eq!(close_in(&mut [], 0, 1), Err(EBADF));
354	    }
355	
356	    #[test]
357	    fn open_hands_out_the_lowest_free_descriptor() {
358	        // POSIX's rule, and the only thing about `open` a client can observe
359	        // without reading the file. A `.rposition()` scan would return 7 here and
360	        // pass every "did I get a descriptor" check.
361	        let mut r = rows();
362	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(3));
363	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(4));
364	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(5));
365	    }
366	
367	    #[test]
368	    fn a_closed_descriptor_is_reused_by_the_next_open() {
369	        // The round trip the `fs.fd` boot probe drives: open, open, close both,
370	        // re-open must land back on 3.
371	        let mut r = rows();
372	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(3));
373	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(4));
374	        assert_eq!(close_in(&mut r, 0, 3), Ok(()));
375	        assert_eq!(close_in(&mut r, 0, 4), Ok(()));
376	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(3));
377	        // ...and with 3 taken again, the next is 4 — so `close` really freed both
378	        // rather than leaving a hole the scan skipped.
379	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(4));
380	    }
381	
382	    #[test]
383	    fn open_never_hands_out_a_standard_descriptor() {
384	        // Even with the row otherwise empty: 0/1/2 are pre-opened, and the scan
385	        // starts above them.
386	        let mut r = rows();
387	        for _ in FIRST_FREE_FD..NR_FDS {
388	            let fd = alloc_in(&mut r, 0, FILE).unwrap();
389	            assert!(fd >= FIRST_FREE_FD as i32, "open returned fd {fd}");
390	        }
391	    }
392	
393	    #[test]
394	    fn a_full_row_is_emfile_not_a_silent_overwrite() {
395	        // `EMFILE` rather than `EBADF`: "you have too many files open" is a
396	        // different thing to tell a caller than "that descriptor is nonsense",
397	        // and overwriting an open descriptor would lose a file silently.
398	        let mut r = rows();
399	        for _ in FIRST_FREE_FD..NR_FDS {
400	            assert!(alloc_in(&mut r, 0, FILE).is_ok());
401	        }
402	        assert_eq!(alloc_in(&mut r, 0, FILE), Err(EMFILE));
403	        // The other row is untouched, so "full" is per process.
404	        assert_eq!(alloc_in(&mut r, 1, FILE), Ok(3));
405	    }
406	
407	    #[test]
408	    fn closing_an_unopened_descriptor_is_ebadf() {
409	        // Closing twice is an error, not a no-op.
410	        let mut r = rows();
411	        assert_eq!(close_in(&mut r, 0, 3), Err(EBADF));
412	        assert_eq!(alloc_in(&mut r, 0, FILE), Ok(3));
413	        assert_eq!(close_in(&mut r, 0, 3), Ok(()));
414	        assert_eq!(close_in(&mut r, 0, 3), Err(EBADF));
415	        for fd in [NR_FDS as i32, -1, i32::MAX] {
416	            assert_eq!(close_in(&mut r, 0, fd), Err(EBADF), "fd {fd}");
417	        }
418	    }
419	
420	    #[test]
421	    fn advance_moves_a_files_position_and_nothing_else() {
422	        let mut r = rows();
423	        assert_eq!(alloc_in(&mut r, 0, Fd::File { ino: 5, pos: 0 }), Ok(3));
424	        advance_in(&mut r, 0, 3, 31);
425	        assert_eq!(resolve_in(&r, 0, 3), Ok(Fd::File { ino: 5, pos: 31 }));
426	        advance_in(&mut r, 0, 3, 9);
427	        assert_eq!(resolve_in(&r, 0, 3), Ok(Fd::File { ino: 5, pos: 40 }));
428	        // The inode is not touched, and the other descriptors are not either.
429	        assert_eq!(resolve_in(&r, 0, 1), Ok(CONSOLE));
430	    }
431	
432	    #[test]
433	    fn advance_is_a_no_op_on_a_character_device_or_a_closed_descriptor() {
434	        // A console has no position. Advancing one must not silently turn it into
435	        // a file, and advancing a closed descriptor must not open one.
436	        let mut r = rows();
437	        advance_in(&mut r, 0, 1, 100);
438	        assert_eq!(resolve_in(&r, 0, 1), Ok(CONSOLE));
439	        advance_in(&mut r, 0, 3, 100);
440	        assert_eq!(resolve_in(&r, 0, 3), Err(EBADF));
441	    }
442	
443	    #[test]
444	    fn a_position_saturates_rather_than_wrapping() {
445	        // A wrapped position would send the next read back to the start of the
446	        // file instead of reporting EOF — silently returning the wrong bytes,
447	        // which is the failure mode a filesystem must not have.
448	        let mut r = rows();
449	        assert_eq!(
450	            alloc_in(
451	                &mut r,
452	                0,
453	                Fd::File {
454	                    ino: 5,
455	                    pos: u64::MAX - 3
456	                }
457	            ),
458	            Ok(3)
459	        );
460	        advance_in(&mut r, 0, 3, 100);
461	        assert_eq!(
462	            resolve_in(&r, 0, 3),
463	            Ok(Fd::File {
464	                ino: 5,
465	                pos: u64::MAX
466	            })
467	        );
468	    }
469	
470	    #[test]
471	    fn the_live_table_round_trips_through_its_wrappers() {
472	        // The four `unsafe` wrappers, exercised once each against the real static
473	        // — the only thing here that is not covered by the pure helpers. Uses a
474	        // high proc number so it cannot collide with another test's expectations
475	        // about proc 0's row.
476	        let p = NR_SERVED_PROCS as i32 - 1;
477	        let fd = alloc(p, Fd::File { ino: 9, pos: 0 }).expect("a free descriptor");
478	        assert_eq!(resolve(p, fd), Ok(Fd::File { ino: 9, pos: 0 }));
479	        advance(p, fd, 7);
480	        assert_eq!(resolve(p, fd), Ok(Fd::File { ino: 9, pos: 7 }));
481	        assert_eq!(close(p, fd), Ok(()));
482	        assert_eq!(resolve(p, fd), Err(EBADF));
483	    }
484	}
