3	//! Path traversal and read policy, allocator-free (slice 5.8).
4	//!
5	//! This is the `Vec`-free rewrite of `tools/mkfs-mfs`'s `verify.rs`, which is the
6	//! reference implementation: same decoders, same zone resolver, same directory
7	//! walk, with `block()` replaced by a `BDEV_READ`. The structure is deliberately
8	//! mirrored so the two can be diffed, and the `fs.selfcheck` boot marker is the
9	//! one place the two readers meet over a real image.
10	//!
11	//! Two of `verify.rs`'s functions could not survive the move to `no_std`:
12	//!
13	//!   * `read_inode_bytes` materializes a whole directory into a `Vec`. The server
14	//!     has one 4 KiB block buffer and a one-page stack, so it **streams** instead —
15	//!     one block at a time, asking [`find_in_block`] about each. That is why this
16	//!     module offers a per-block search rather than a directory reader.
17	//!   * `read_dir` is absent entirely. Nothing needs it: there is no `GETDENTS`
18	//!     request, on the `CDEV_READ` precedent that a request without a consumer is
19	//!     better absent than stubbed.
20	//!
21	//! ## Every bound here exists to stop a loop
22	//!
23	//! The server's loop bounds all come from the *device*, and a corrupt image is
24	//! not a hypothetical the way it is for a filesystem with an `fsck`: a directory
25	//! whose inode claims `size = i32::MAX` would spin MFS forever, and a spinning
26	//! MFS blocks VFS, which blocks init, which takes the slice-5.4-to-5.6 markers
27	//! down with it. So a negative size is [`EIO`], an over-large directory is
28	//! [`EIO`], and every zone is bounds-checked ([`zone_ok`]) *before* it becomes a
29	//! `BDEV_READ`. None of this is reachable from a VFS probe — VFS cannot forge a
30	//! corrupt inode — which is exactly why it needs unit tests instead.
31	
32	use minixrs_kernel_shared::callnr::FS_MAX_IO;
33	use minixrs_kernel_shared::error::{EINVAL, EIO, ENAMETOOLONG};
34	
35	use crate::MFS_BLOCK_SIZE;
36	use crate::dirent::{NAME_MAX, iter_block};
37	
38	/// Largest directory this server will scan, in bytes: the seven direct zones.
39	///
40	/// `tools/mkfs-mfs` never builds a directory past one block (a 4 KiB block holds
41	/// 64 entries), so this is 7× headroom for the images that exist. A directory
42	/// larger than this is [`EIO`] rather than a silent truncation — answering
43	/// `ENOENT` for a name that is really there is the one failure mode a filesystem
44	/// must not have, and "I cannot read this" is the honest alternative.
45	pub const MAX_DIR_BYTES: usize = 7 * MFS_BLOCK_SIZE;
46	
47	/// What one [`FS_READ`](minixrs_kernel_shared::callnr::FS_READ) round moves.
48	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
49	pub struct Chunk {
50	    /// Bytes to transfer. **`0` is end of file**, not an error — and it is the
51	    /// only way a client learns where a file ends, since no size is cached
52	    /// anywhere along the path.
53	    pub len: usize,
54	    /// Byte offset within the block that backs the transfer. A chunk never
55	    /// straddles two blocks, which is what lets the server stage through a single
56	    /// block buffer.
57	    pub off_in_block: usize,
58	}
59	
60	/// Check an absolute path and hand it back.
61	///
62	/// The three ways a path can be malformed, in the order a caller should hear
63	/// about them:
64	///
65	/// 1. Empty, or not starting with `/` → `EINVAL`. There is no working directory
66	///    on minix.rs and no `chdir`, so a relative path is not a thing that could be
67	///    resolved — it is a malformed request, not a missing file.
68	/// 2. A component longer than [`NAME_MAX`] → `ENAMETOOLONG`. MinixFS cannot
69	///    *store* such a name, so no image can contain one and `ENOENT` would be a
70	///    less informative way of saying the same thing.
71	/// 3. Otherwise the path itself, unchanged.
72	///
73	/// The overall length cap (`FS_PATH_MAX`) is enforced by the wire codec in
74	/// `proto.rs`, where the field's width is: a path that filled its field with no
75	/// NUL never becomes a `&str` at all.
76	pub fn parse_path(path: &str) -> Result<&str, i32> {
77	    if !path.starts_with('/') {
78	        return Err(EINVAL);
79	    }
80	    for component in components(path) {
81	        if component.len() > NAME_MAX {
82	            return Err(ENAMETOOLONG);
83	        }
84	    }
85	    Ok(path)
86	}
87	
88	/// The non-empty components of a path, in order.
89	///
90	/// Repeated and trailing slashes collapse — `/etc//motd/` walks the same two
91	/// components as `/etc/motd` — which is POSIX's rule and `verify.rs`'s. `"/"`
92	/// yields nothing at all, so it resolves to the root inode without a single
93	/// directory read.
94	pub fn components(path: &str) -> impl Iterator<Item = &str> {
95	    path.split('/').filter(|c| !c.is_empty())
96	}
97	
98	/// Find `name` among the directory entries of one fetched block.
99	///
100	/// **Returns the inode number by value**, so the caller's borrow of the block
101	/// buffer ends at the call. That is not a style preference: the buffer is a
102	/// single shared staging area, and the next thing the caller does is fetch the
103	/// *inode's* block into it. Returning a `DirEntry` — or worse a `&str` into the
104	/// block — would make holding a name across that fetch expressible.
105	///
106	/// Free slots (`ino == 0`) are skipped by [`iter_block`], and a name that is not
107	/// valid UTF-8 decodes to `""`, which cannot equal any component `parse_path`
108	/// accepted. So neither can be matched by accident.
109	pub fn find_in_block(block: &[u8], name: &str) -> Option<u32> {
110	    iter_block(block)
111	        .find(|e| e.name_str() == name)
112	        .map(|e| e.ino)
113	}
114	
115	/// Validate a directory's size and return it as a scan bound.
116	///
117	/// Separate from [`clamp_read`] because the two answer different questions: a
118	/// *file* read clamps to the size, while a *directory* scan has to reject one it
119	/// cannot bound. See [`MAX_DIR_BYTES`].
120	pub fn dir_size(size: i32) -> Result<usize, i32> {
121	    if size < 0 {
122	        return Err(EIO);
123	    }
124	    let size = size as usize;
125	    if size > MAX_DIR_BYTES {
126	        return Err(EIO);
127	    }
128	    Ok(size)
129	}
130	
131	/// Decide how much of one read request to serve in this round.
132	///
133	/// `size` is the inode's (signed on disk, so a negative one is a corrupt inode →
134	/// `EIO`), `pos` the file offset, `len` the bytes asked for, `bs` the block size.
135	///
136	/// Four clamps, and the order does not matter because they are all minima — but
137	/// each has its own reason:
138	///
139	/// 1. **To the file's size.** Past the end is [`Chunk::len`] `== 0`, i.e. EOF.
140	/// 2. **To [`FS_MAX_IO`].** One request moves at most one block, because that is
141	///    the staging buffer a server on a one-page stack can afford. This is a
142	///    **short read, not `EINVAL`** — the deliberate departure from `BDEV_READ`,
143	///    whose client is a filesystem that cannot interpret half a block, towards
144	///    `CDEV_WRITE`, whose client is VFS and whose job is hiding staging from
145	///    POSIX. A read is short at EOF regardless, so a client that could not cope
146	///    with a short read could not use this request at all.
147	/// 3. **To the end of the block containing `pos`.** The invariant that makes one
148	///    block buffer sufficient: a chunk never straddles two blocks.
149	/// 4. `len < 0` → `EINVAL`, before any of the above. Left unchecked it would
150	///    widen into a ~16 EiB `u64` byte count on the safecopy.
151	///
152	/// `bs == 0` is `EINVAL` rather than a division by zero — it cannot happen (the
153	/// superblock validator rejects it) but this function is total.
154	pub fn clamp_read(size: i32, pos: u64, len: i32, bs: usize) -> Result<Chunk, i32> {
155	    if size < 0 {
156	        return Err(EIO);
157	    }
158	    if len < 0 || bs == 0 {
159	        return Err(EINVAL);
160	    }
161	    let size = size as u64;
162	    let off_in_block = (pos % bs as u64) as usize;
163	    if pos >= size {
164	        // EOF. `off_in_block` is still reported so the value is total, but a
165	        // zero-length chunk names no bytes and the caller fetches no block.
166	        return Ok(Chunk {
167	            len: 0,
168	            off_in_block,
169	        });
170	    }
171	
172	    let remaining = size - pos;
173	    let to_block_end = bs - off_in_block;
174	    // Each term is already bounded by a `usize` quantity, so the `as usize` on
175	    // `remaining` cannot truncate on any target this runs on — but take the
176	    // minimum in `u64` first so it is true by construction rather than by
177	    // inspection.
178	    let len = (len as u64)
179	        .min(remaining)
180	        .min(FS_MAX_IO as u64)
181	        .min(to_block_end as u64) as usize;
182	    Ok(Chunk { len, off_in_block })
183	}
184	
185	/// May zone `zone` be read from a device holding `blocks` blocks?
186	///
187	/// Zone 0 is never a data zone in MinixFS (it is the boot block), so a zero here
188	/// means a hole reached this function by mistake rather than being handled as one
189	/// — reject it. The upper bound is what stops a corrupt inode turning into a
190	/// `BDEV_READ` past the end of the device, which the driver would refuse anyway;
191	/// checking here makes the refusal an `EIO` about the *filesystem* rather than an
192	/// `EINVAL` about the device.
193	pub fn zone_ok(zone: u32, blocks: u32) -> bool {
194	    zone != 0 && zone < blocks
195	}
196	
197	#[cfg(test)]
198	mod tests {
199	    use super::*;
200	    use crate::dirent::DirEntry;
201	    use crate::inode::ROOT_INODE;
202	
203	    const BS: usize = MFS_BLOCK_SIZE;
204	
205	    #[test]
206	    fn an_absolute_path_passes_through() {
207	        for p in ["/", "/etc", "/etc/motd", "/bin/hello"] {
208	            assert_eq!(parse_path(p), Ok(p), "{p}");
209	        }
210	    }
211	
212	    #[test]
213	    fn a_relative_or_empty_path_is_einval() {
214	        // There is no working directory on minix.rs, so a relative path is a
215	        // malformed request rather than a missing file.
216	        for p in ["", "etc/motd", ".", "..", "motd"] {
217	            assert_eq!(parse_path(p), Err(EINVAL), "{p}");
218	        }
219	    }
220	
221	    #[test]
222	    fn a_component_longer_than_the_format_allows_is_enametoolong() {
223	        // MinixFS cannot store a name this long, so no image can contain one:
224	        // `/` followed by NAME_MAX + 1 letters.
225	        let mut buf = [b'a'; NAME_MAX + 2];
226	        buf[0] = b'/';
227	        let too_long = core::str::from_utf8(&buf).unwrap();
228	        assert_eq!(too_long.len(), NAME_MAX + 2);
229	        assert_eq!(parse_path(too_long), Err(ENAMETOOLONG));
230	
231	        // Exactly NAME_MAX is fine — the boundary itself, not one inside it.
232	        let ok = core::str::from_utf8(&buf[..NAME_MAX + 1]).unwrap();
233	        assert_eq!(parse_path(ok), Ok(ok));
234	    }
235	
236	    #[test]
237	    fn components_collapse_repeated_and_trailing_slashes() {
238	        let mut seen = [""; 4];
239	        let mut n = 0;
240	        for c in components("/etc//motd/") {
241	            seen[n] = c;
242	            n += 1;
243	        }
244	        assert_eq!(n, 2);
245	        assert_eq!(seen[0], "etc");
246	        assert_eq!(seen[1], "motd");
247	    }
248	
249	    #[test]
250	    fn the_root_path_has_no_components() {
251	        // So `/` resolves to the root inode without a single directory read.
252	        assert_eq!(components("/").count(), 0);
253	        assert_eq!(components("///").count(), 0);
254	    }
255	
256	    /// One directory block holding `.`, `..`, and two named entries.
257	    fn dir_block() -> [u8; BS] {
258	        let mut b = [0u8; BS];
259	        for (slot, (ino, name)) in [
260	            (ROOT_INODE, &b"."[..]),
261	            (ROOT_INODE, &b".."[..]),
262	            (5u32, &b"motd"[..]),
263	            (9u32, &b"pattern"[..]),
264	        ]
265	        .into_iter()
266	        .enumerate()
267	        {
268	            let e = DirEntry::new(ino, name).unwrap();
269	            b[slot * 64..(slot + 1) * 64].copy_from_slice(&e.to_le_bytes());
270	        }
271	        b
272	    }
273	
274	    #[test]
275	    fn find_in_block_returns_the_named_entry() {
276	        let b = dir_block();
277	        assert_eq!(find_in_block(&b, "motd"), Some(5));
278	        assert_eq!(find_in_block(&b, "pattern"), Some(9));
279	        assert_eq!(find_in_block(&b, "."), Some(ROOT_INODE));
280	        assert_eq!(find_in_block(&b, ".."), Some(ROOT_INODE));
281	    }
282	
283	    #[test]
284	    fn find_in_block_does_not_match_a_prefix_or_a_free_slot() {
285	        // A prefix match would resolve `/etc/mot` to `motd`; a free slot decodes
286	        // to an empty name, which must not match an empty query either (though
287	        // `parse_path`'s components are never empty).
288	        let b = dir_block();
289	        assert_eq!(find_in_block(&b, "mot"), None);
290	        assert_eq!(find_in_block(&b, "motdd"), None);
291	        assert_eq!(find_in_block(&b, ""), None);
292	        assert_eq!(find_in_block(&[0u8; BS], "motd"), None);
293	    }
294	
295	    #[test]
296	    fn find_in_block_ignores_a_trailing_partial_entry() {
297	        // A short block must not synthesize an entry out of whatever followed it.
298	        let b = dir_block();
299	        assert_eq!(find_in_block(&b[..64 * 3 + 40], "pattern"), None);
300	        assert_eq!(find_in_block(&b[..64 * 3 + 40], "motd"), Some(5));
301	        assert_eq!(find_in_block(&[], "motd"), None);
302	    }
303	
304	    #[test]
305	    fn a_directory_size_is_bounded() {
306	        assert_eq!(dir_size(0), Ok(0));
307	        assert_eq!(dir_size(BS as i32), Ok(BS));
308	        assert_eq!(dir_size(MAX_DIR_BYTES as i32), Ok(MAX_DIR_BYTES));
309	    }
310	
311	    #[test]
312	    fn a_corrupt_directory_size_is_eio_rather_than_an_unbounded_scan() {
313	        // The bound that stops a corrupt inode spinning the server forever. Both
314	        // ends: a negative size (which would widen into ~2 GiB as a `usize`) and
315	        // one past what this server will scan.
316	        assert_eq!(dir_size(-1), Err(EIO));
317	        assert_eq!(dir_size(i32::MIN), Err(EIO));
318	        assert_eq!(dir_size(MAX_DIR_BYTES as i32 + 1), Err(EIO));
319	        assert_eq!(dir_size(i32::MAX), Err(EIO));
320	    }
321	
322	    #[test]
323	    fn a_whole_small_file_reads_in_one_chunk() {
324	        assert_eq!(
325	            clamp_read(31, 0, 4096, BS),
326	            Ok(Chunk {
327	                len: 31,
328	                off_in_block: 0
329	            })
330	        );
331	    }
332	
333	    #[test]
334	    fn a_read_never_straddles_a_block_boundary() {
335	        // The invariant that makes one block buffer sufficient. Asking for 4096
336	        // bytes from 100 bytes into a block yields the rest of that block only.
337	        let c = clamp_read(BS as i32 * 4, 100, 4096, BS).unwrap();
338	        assert_eq!(c.off_in_block, 100);
339	        assert_eq!(c.len, BS - 100);
340	        assert_eq!(c.off_in_block + c.len, BS);
341	
342	        // ...and driving it round the loop lands exactly on the boundary.
343	        let c = clamp_read(BS as i32 * 4, BS as u64 - 1, 4096, BS).unwrap();
344	        assert_eq!(c.len, 1);
345	        assert_eq!(c.off_in_block, BS - 1);
346	    }
347	
348	    #[test]
349	    fn a_read_past_the_end_of_the_file_is_zero_not_an_error() {
350	        // EOF is `len == 0`, the only way a client learns where a file ends.
351	        for pos in [31u64, 32, 4096, u64::MAX] {
352	            let c = clamp_read(31, pos, 4096, BS).unwrap();
353	            assert_eq!(c.len, 0, "pos {pos}");
354	        }
355	        // An empty file is EOF at offset 0.
356	        assert_eq!(clamp_read(0, 0, 4096, BS).unwrap().len, 0);
357	    }
358	
359	    #[test]
360	    fn an_over_long_request_is_clamped_rather_than_refused() {
361	        // The deliberate departure from BDEV_READ, whose answer here is EINVAL.
362	        let big = BS as i32 * 4;
363	        assert_eq!(clamp_read(big, 0, i32::MAX, BS).unwrap().len, FS_MAX_IO);
364	        assert_eq!(
365	            clamp_read(big, 0, FS_MAX_IO as i32 + 1, BS).unwrap().len,
366	            FS_MAX_IO
367	        );
368	    }
369	
370	    #[test]
371	    fn a_negative_length_or_size_is_rejected() {
372	        // A negative length would widen into a ~16 EiB `u64` on the safecopy; a
373	        // negative size is a corrupt inode, which is a different failure.
374	        assert_eq!(clamp_read(100, 0, -1, BS), Err(EINVAL));
375	        assert_eq!(clamp_read(100, 0, i32::MIN, BS), Err(EINVAL));
376	        assert_eq!(clamp_read(-1, 0, 8, BS), Err(EIO));
377	        // The size check comes first: a request wrong in both ways reports the
378	        // one that is about the filesystem rather than the one about the caller.
379	        assert_eq!(clamp_read(-1, 0, -1, BS), Err(EIO));
380	    }
381	
382	    #[test]
383	    fn a_zero_block_size_is_einval_rather_than_a_division_by_zero() {
384	        // Unreachable — the superblock validator rejects it — but this function
385	        // is total, so it has to say something.
386	        assert_eq!(clamp_read(100, 0, 8, 0), Err(EINVAL));
387	    }
388	
389	    #[test]
390	    fn driving_clamp_read_round_a_whole_file_terminates_at_the_size() {
391	        // The property, over a file that spans several blocks and ends mid-block.
392	        let size = BS * 2 + 37;
393	        let mut pos = 0u64;
394	        let mut total = 0usize;
395	        let mut rounds = 0;
396	        loop {
397	            rounds += 1;
398	            assert!(rounds <= 8, "the read loop failed to converge");
399	            let c = clamp_read(size as i32, pos, i32::MAX, BS).unwrap();
400	            if c.len == 0 {
401	                break;
402	            }
403	            assert!(c.off_in_block + c.len <= BS, "chunk straddles a block");
404	            pos += c.len as u64;
405	            total += c.len;
406	        }
407	        assert_eq!(total, size);
408	        assert_eq!(rounds, 4);
409	    }
410	
411	    #[test]
412	    fn a_zone_must_be_non_zero_and_inside_the_device() {
413	        assert!(zone_ok(1, 256));
414	        assert!(zone_ok(255, 256));
415	        // Zone 0 is the boot block: a hole that reached this call by mistake.
416	        assert!(!zone_ok(0, 256));
417	        // Past the end — what stops a corrupt inode becoming a BDEV_READ off the
418	        // end of the device.
419	        assert!(!zone_ok(256, 256));
420	        assert!(!zone_ok(u32::MAX, 256));
421	        // A device with no blocks admits nothing.
422	        assert!(!zone_ok(1, 0));
423	    }
424	}
